-- Ninguna persona, empresa, autorización, placa, teléfono o correo corresponde a datos reales:
-- correos en example.com (dominio reservado), teléfonos 81 5555 xxxx y autorizaciones «NL-EJ-…».
-- Las calles son nombres comunes con números arbitrarios; no describen recintos identificables.
-- NUNCA cargar en la base "manifiestos" (New-Ejemplo.ps1 lo impide).
SET client_encoding = 'UTF8';
CREATE FUNCTION pg_temp.uid(t text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$ SELECT md5('ejemplo-manifiestos:' || t)::uuid $$;
