CREATE FUNCTION pg_temp.ej_succion(cap text, jornada text, parada text, banos int, fecha timestamptz, lat numeric, lon numeric) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    VALUES ('e1000000-0000-4000-8000-000000000001', 'e1000000-0000-4000-8000-000000000003', pg_temp.uid(cap), pg_temp.uid('asignacion:san'), pg_temp.uid('dispositivo:san'), pg_temp.uid('instalacion:san'), fecha);
    VALUES ('e1000000-0000-4000-8000-000000000001', 'e1000000-0000-4000-8000-000000000003', pg_temp.uid(cap || ':foto'), pg_temp.uid(cap), 'FOTO', sha256(cap::bytea), 1000, lat, lon, 8, fecha);
        asignacion_trabajo, revision_trabajo, version_datos, requiere_firma_cliente, datos_orden, banos, banos_asignados)
    VALUES ('e1000000-0000-4000-8000-000000000001', 'e1000000-0000-4000-8000-000000000003', pg_temp.uid(cap), 'SERVICIO_SANITARIOS', pg_temp.uid('persona:o5'), pg_temp.uid('identidad:san'),
        pg_temp.uid(parada), pg_temp.uid(jornada), 'ejemplo', '1', '1', false, convert_to('{}', 'UTF8'), banos, banos);
END $$;
